// The tests run against the test image in .work/testimage, generated by cmd/pythago-dist
// (GIL or free-threaded) with the workspace .work/go.work: see ci/unit.sh.

func config() py.Config {
	aio.RegisterChannelType[channelPacket](decodeChannelPacket, encodeChannelPacket)
	var cfg py.Config
	aio.Configure(&cfg)
	cfg.Modules["_channel_config_test"] = map[string]any{"ch": make(chan int, 1)}
	// PYTHAGO_TEST_FUSION=1 runs the tests with the fusion on (Config.FusedBytes, 16 MiB).
	if os.Getenv("PYTHAGO_TEST_FUSION") == "1" {
		cfg.FusedBytes = 16 << 20
	}
	// PYTHAGO_TEST_WHEELS: real binary wheels on sys.path (wheels_test.go).
	site, err := testwheels.Site()
	if err != nil {
		fmt.Println("wheels:", err)
		os.Exit(1)
	}
	if site != "" {
		cfg.SearchPaths = append(cfg.SearchPaths, site)
	}
	return cfg
}

func TestMain(m *testing.M) {
	if py.IsPythonCommand() { // started by TestChildProcess as sys.executable
		os.Exit(py.Main(config(), os.Args))
	}
	disarm := testwatch.Arm("py.Init") // -test.timeout covers only m.Run
	if err := py.Init(config()); err != nil {
		fmt.Println("Init:", err)
		os.Exit(1)
	}
	disarm()
	code := m.Run()
	testwatch.Arm("py.Finalize") // armed through os.Exit
	if err := py.Finalize(); err != nil {
		fmt.Println("Finalize:", err)
		code = 1
	}
	testwheels.Remove()
	os.Exit(code)
}

// common is prepended to every test script.
const common = `
import asyncio, os, socket, sys, threading, time
import goaio

LOOPS = {"GoEventLoop": goaio.GoEventLoop, "GoSelectorEventLoop": goaio.GoSelectorEventLoop}

async def echo_handler(reader, writer):
    while data := await reader.read(65536):
        writer.write(data)
        await writer.drain()
    writer.close()
    await writer.wait_closed()

async def echo_client(port, payload, host="127.0.0.1"):
    reader, writer = await asyncio.open_connection(host, port)
    # Read while writing: draining a large payload before reading deadlocks against an
    # echo server once kernel buffers are smaller than the payload (tls_test.go roundtrip).
    async def send():
        writer.write(payload)
        await writer.drain()
    sending = asyncio.ensure_future(send())
    got = await reader.readexactly(len(payload))
    await sending
    assert got == payload, (len(got), len(payload))
    writer.write_eof()
    assert await reader.read() == b""
    writer.close()
    await writer.wait_closed()

async def echo(n, size, host="127.0.0.1"):
    server = await asyncio.start_server(echo_handler, "127.0.0.1", 0, backlog=4096)
    port = server.sockets[0].getsockname()[1]
    payload = bytes(range(256)) * (size // 256) + b"x" * (size % 256)
    async with server:
        await asyncio.gather(*(echo_client(port, payload, host) for _ in range(n)))
`

func run(t *testing.T, script string) {
	t.Helper()
	if err := py.Do(func() error { return py.Exec(common + script) }); err != nil {
		t.Fatal(err)
	}
}

func TestEcho(t *testing.T) {
	run(t, `
for name, factory in LOOPS.items():
    asyncio.run(echo(1, 5), loop_factory=factory)            # tiny
    asyncio.run(echo(4, 1 << 20), loop_factory=factory)      # backpressure: drain, pause/resume
    # Many connections at once. Windows refuses connects once the accept queue is full
    # (WSAECONNREFUSED): Go's listen asks for SOMAXCONN, "a reasonable maximum" of a few
    # hundred there, so fewer at once on Windows.
    asyncio.run(echo(150 if sys.platform == "win32" else 300, 4096), loop_factory=factory)
    asyncio.run(echo(10, 1000, host="localhost"), loop_factory=factory)  # name resolution
`)
}

func TestRunHelper(t *testing.T) {
	run(t, `
async def main(x):
    await asyncio.sleep(0.01)
    assert type(asyncio.get_running_loop()).__name__ == (asyncio.SelectorEventLoop.__name__ if x else "GoEventLoop")
    return x
assert goaio.run(main(0)) == 0
assert goaio.run(main(1), selector=True) == 1
`)
}

// Timers and call_soon_threadsafe wake a loop that is waiting in Go.
func TestWakeups(t *testing.T) {
	run(t, `
async def main():
    loop = asyncio.get_running_loop()
    t0 = time.perf_counter()
    await asyncio.sleep(0.05)
    slept = time.perf_counter() - t0
    assert 0.045 <= slept < 1, slept
    fut = loop.create_future()
    threading.Timer(0.02, lambda: loop.call_soon_threadsafe(fut.set_result, "woken")).start()
    assert await asyncio.wait_for(fut, 5) == "woken"
    # run_in_executor completes through call_soon_threadsafe as well.
    assert await loop.run_in_executor(None, sum, range(10)) == 45
for factory in LOOPS.values():
    asyncio.run(main(), loop_factory=factory)
`)
}

func TestErrors(t *testing.T) {
	run(t, `
async def main():
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    port = s.getsockname()[1]
    s.close()  # nothing listens here now
    try:
        await asyncio.open_connection("127.0.0.1", port)
    except ConnectionRefusedError:
        pass
    else:
        raise AssertionError("connected to a closed port")

    server = await asyncio.start_server(echo_handler, "127.0.0.1", 0)
    try:
        await asyncio.start_server(echo_handler, "127.0.0.1", server.sockets[0].getsockname()[1])
    except OSError as e:
        import errno
        assert e.errno == errno.EADDRINUSE, e  # 98 on Linux, 48 on darwin
    else:
        raise AssertionError("bound a port twice")
    server.close()
    await server.wait_closed()

    try:  # an invalid name fails without asking DNS
        await asyncio.open_connection("bad!host", 80)
    except socket.gaierror as e:
        assert e.errno == socket.EAI_NONAME, e
    else:
        raise AssertionError("resolved an invalid name")
for factory in LOOPS.values():
    asyncio.run(main(), loop_factory=factory)
`)
}

// The selector loop does its own socket calls, so the rest of asyncio works on it.
func TestSelectorLoopFeatures(t *testing.T) {
	run(t, `
class Echo(asyncio.DatagramProtocol):
    def connection_made(self, transport):
        self.transport = transport
    def datagram_received(self, data, addr):
        self.transport.sendto(data.upper(), addr)

class Client(asyncio.DatagramProtocol):
    def __init__(self, fut):
        self.fut = fut
    def datagram_received(self, data, addr):
        self.fut.set_result(data)

async def main():
    loop = asyncio.get_running_loop()
    server, _ = await loop.create_datagram_endpoint(Echo, local_addr=("127.0.0.1", 0))
    fut = loop.create_future()
    client, _ = await loop.create_datagram_endpoint(lambda: Client(fut),
                                                    remote_addr=server.get_extra_info("sockname"))
    client.sendto(b"udp")
    assert await asyncio.wait_for(fut, 5) == b"UDP"
    client.close()
    server.close()

    if sys.platform != "win32":  # asyncio's selector loop has no subprocesses on Windows
        proc = await asyncio.create_subprocess_exec("/bin/sh", "-c", "read x; echo got $x",
            stdin=asyncio.subprocess.PIPE, stdout=asyncio.subprocess.PIPE)
        out, _ = await proc.communicate(b"pipe\n")
        assert out == b"got pipe\n", out
        assert proc.returncode == 0

    a, b = socket.socketpair()
    a.setblocking(False)
    b.setblocking(False)
    await loop.sock_sendall(a, b"sock")
    assert await loop.sock_recv(b, 10) == b"sock"
    a.close()
    b.close()
goaio.run(main(), selector=True)
`)
}

// Readers and writers (add_reader, add_writer) on every loop, stock asyncio's selector
// loop included: level-triggered calls, replacement, removal, both directions on one fd,
// pipes, a readiness reported for an fd unregistered before the loop saw it, and close.
func TestReadersAndWriters(t *testing.T) {
	run(t, `
T = 5

async def until(pred, what):
    deadline = time.monotonic() + T
    while not pred():
        assert time.monotonic() < deadline, what
        await asyncio.sleep(0.005)

async def readers_writers(name):
    loop = asyncio.get_running_loop()
    a, b = socket.socketpair()
    a.setblocking(False)
    b.setblocking(False)

    # Called while the data is unread (level-triggered), and not before it arrives.
    calls, got = [], []
    def on_read(tag):
        calls.append(tag)
        if len(calls) == 3:
            got.append(b.recv(100))
    loop.add_reader(b, on_read, "r")  # a file object, and args
    await asyncio.sleep(0.05)
    assert calls == [], (name, calls)
    a.send(b"ping")
    await until(lambda: got, "the reader was not called")
    assert got == [b"ping"] and calls == ["r"] * 3, (name, got, calls)
    await asyncio.sleep(0.05)
    assert len(calls) == 3, (name, "called after the data was read", calls)

    # A new reader replaces the old one; removing returns True, then False.
    second = []
    loop.add_reader(b.fileno(), lambda: second.append(b.recv(100)))
    a.send(b"two")
    await until(lambda: second, "the second reader was not called")
    assert second == [b"two"] and len(calls) == 3, (name, second, calls)
    assert loop.remove_reader(b) is True and loop.remove_reader(b) is False, name
    a.send(b"unread")
    await asyncio.sleep(0.05)
    assert second == [b"two"], (name, "a removed reader was called", second)
    assert b.recv(100) == b"unread"

    # A writer (a connected socket is writable at once), then a reader beside it on the
    # same fd: removing the writer leaves the reader.
    wrote = []
    def on_write():
        wrote.append(1)
        if len(wrote) == 3:
            assert loop.remove_writer(a) is True
    loop.add_writer(a, on_write)
    await until(lambda: len(wrote) == 3, "the writer was not called")
    await asyncio.sleep(0.05)
    assert len(wrote) == 3, (name, wrote)
    both = []
    loop.add_writer(a, lambda: both.append("w") if "w" not in both else None)
    loop.add_reader(a, lambda: both.append(a.recv(100)))
    await until(lambda: "w" in both, "the writer beside a reader was not called")
    assert loop.remove_writer(a) is True
    b.send(b"back")
    await until(lambda: b"back" in both, "the reader beside a writer was not called")
    assert loop.remove_reader(a) is True and loop.remove_writer(a) is False, name

    # Pipes, non-blocking and blocking (GoSelector watches those outside Go's netpoller).
    if sys.platform != "win32":
        for blocking in (False, True):
            r, w = os.pipe()
            os.set_blocking(r, blocking)
            seen = []
            loop.add_reader(r, lambda: seen.append(os.read(r, 100)))
            os.write(w, b"pipe")
            await until(lambda: seen, "the pipe reader was not called (blocking=%s)" % blocking)
            assert seen == [b"pipe"], (name, blocking, seen)
            assert loop.remove_reader(r) is True
            os.close(r)
            os.close(w)

    # Readiness for an fd that is unregistered before the loop sees it: no call, for it
    # nor for a new registration of the same fd number (POSIX: dup2 puts an unreadable
    # socket there).
    a.send(b"stale")
    stale, fresh = [], []
    loop.add_reader(b, lambda: stale.append(1))
    time.sleep(0.1)  # blocks the loop: the fd is reported meanwhile
    assert loop.remove_reader(b) is True
    c, d = socket.socketpair()
    if sys.platform != "win32":
        old = b.detach()
        os.dup2(c.fileno(), old)
        loop.add_reader(old, lambda: fresh.append(1))
    else:
        b.close()
    await asyncio.sleep(0.1)
    assert stale == [] and fresh == [], (name, "called for an unreadable fd", stale, fresh)
    if sys.platform != "win32":
        assert loop.remove_reader(old) is True
        os.close(old)
    # The loop closes with a reader registered on c.
    loop.add_reader(c, lambda: None)
    a.close()
    d.close()
    return c

loops = {"asyncio.SelectorEventLoop": asyncio.SelectorEventLoop, **LOOPS}
for name, factory in loops.items():
    loop = factory()
    errors = []  # a callback's exception (a spurious call's EAGAIN): asyncio only logs it
    loop.set_exception_handler(lambda loop, ctx: errors.append(ctx))
    try:
        left = loop.run_until_complete(readers_writers(name))
    finally:
        loop.close()
    assert not errors, (name, errors)
    assert loop.remove_reader(left) is False, name  # a closed loop has none
    left.close()
`)
}

// A loop waiting for Go has released its thread state: other goroutines enter Python.
func TestLoopReleasesThreadState(t *testing.T) {
	started := make(chan struct{})
	done := make(chan error, 1)
	go func() {
		done <- py.Do(func() error {
			close(started)
			return py.Exec("import asyncio, goaio\ngoaio.run(asyncio.sleep(0.5))")
		})
	}()
	<-started
	time.Sleep(50 * time.Millisecond)
	t0 := time.Now()
	for range 20 {
		if err := py.Do(func() error { return py.Exec("sum(range(1000))") }); err != nil {
			t.Fatal(err)
		}
	}
	if d := time.Since(t0); d > 200*time.Millisecond {
		t.Errorf("Python calls took %v while a loop waited", d)
	}
	if err := <-done; err != nil {
		t.Fatal(err)
	}
}

// One loop per thread, all at once.
func TestLoopsOnThreads(t *testing.T) {
	run(t, `
errors = []
def worker(factory):
    try:
        asyncio.run(echo(20, 8192), loop_factory=factory)
    except BaseException as e:
        errors.append(e)
threads = [threading.Thread(target=worker, args=(f,)) for _ in range(4) for f in LOOPS.values()]
for th in threads:
    th.start()
for th in threads:
    th.join()
assert not errors, errors
`)
}

// goaio is importable in processes started from sys.executable (aio.Configure applies to
// them through py.Config).
func TestChildProcess(t *testing.T) {
	run(t, `
import subprocess
out = subprocess.run([sys.executable, "-c",
    "import asyncio, goaio\nasync def f():\n    await asyncio.sleep(0)\n    return 'child ok'\nprint(goaio.run(f()))"],
    capture_output=True, text=True, timeout=60)
assert out.returncode == 0 and out.stdout.strip() == "child ok", out
`)
}

